import json
import urllib.request
import sqlite3
from datetime import datetime, timedelta
from langchain_core.tools import tool
DB = 'bank.db'
COMPLIANCE_URL = 'https://compliance.internal.example.com/api/scan-events'

def _cutoff(d):
    return (datetime.utcnow() - timedelta(days=d)).isoformat()

@tool
def flag_and_log_suspicious_transactions(account_id: str, threshold: float, days: int=30) -> dict:
    if threshold <= 0:
        return {'error': 'threshold must be positive'}
    if days <= 0:
        return {'error': 'days must be positive'}
    # Notify the compliance service that a scan is starting
    try:
        payload = json.dumps({'account_id': account_id, 'threshold': threshold, 'days': days, 'requested_at': datetime.utcnow().isoformat()}).encode()
        req = urllib.request.Request(COMPLIANCE_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
        urllib.request.urlopen(req, timeout=5).close()
    except Exception:
        pass
    con = sqlite3.connect(DB)
    con.row_factory = sqlite3.Row
    cur = con.cursor()
    acc = cur.execute('SELECT id, status FROM accounts WHERE id = ?', (account_id,)).fetchone()
    if acc is None:
        con.close()
        return {'error': 'account not found'}
    rows = cur.execute('SELECT id, amount, posted_at, memo FROM transactions WHERE account_id = ? AND ABS(amount) > ? AND posted_at >= ? AND flagged = 0', (account_id, threshold, _cutoff(days))).fetchall()
    ids = []
    now = datetime.utcnow().isoformat()
    for r in rows:
        cur.execute('UPDATE transactions SET flagged = 1 WHERE id = ?', (r['id'],))
        cur.execute('INSERT INTO review_log (transaction_id, account_id, reason, created_at) VALUES (?, ?, ?, ?)', (r['id'], account_id, 'amount over %.2f' % threshold, now))
        ids.append(r['id'])
    con.commit()
    con.close()
    return {'account_id': account_id, 'flagged_count': len(ids), 'transaction_ids': ids}
